#include "ContractTemplateRuntime.hpp"
namespace elysium::contracts { static std::uint64_t mix(std::uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;return x;} bool ContractTemplateRuntime::add(ContractTemplate d,std::string&w){if(!d.id||!d.version||d.objectives.empty()||!d.rewardTable){w="invalid template";return false;}for(auto&o:d.objectives)if(!o.type||!o.minCount||o.maxCount<o.minCount){w="invalid objective";return false;}if(!defs_.emplace(d.id,std::move(d)).second){w="duplicate template";return false;}return true;} std::optional<ContractInstance> ContractTemplateRuntime::compile(ContentId id,std::uint64_t seed,std::uint64_t issuer,std::string&w)const{auto i=defs_.find(id);if(i==defs_.end()){w="unknown template";return std::nullopt;}auto&d=i->second;ContractInstance c{mix(id^seed^issuer),id,seed,d.objectives,{}};for(std::size_t n=0;n<d.objectives.size();++n){auto& o=c.objectives[n];auto span=std::uint64_t(o.maxCount-o.minCount)+1;o.minCount=o.maxCount=o.minCount+std::uint32_t(mix(seed+n)%span);}auto pool=d.complicationPool;std::sort(pool.begin(),pool.end());std::uint32_t take=std::min<std::uint32_t>(d.maxComplications,pool.size());for(std::uint32_t n=0;n<take;++n){auto idx=std::size_t(mix(seed+0x100+n)%pool.size());c.complications.push_back(pool[idx]);pool.erase(pool.begin()+idx);}std::sort(c.complications.begin(),c.complications.end());return c;} }